  $page = Invoke-RestMethod -Method Post -Uri 'http://localhost:8080/api/pages' -ContentType 'application/json' -Body '{"collectionNo":"P-DEMO"}'
  $batch = Invoke-RestMethod -Method Post -Uri 'http://localhost:8080/api/batches' -ContentType 'application/json' -Body '{"batchNo":"B-DEMO"}'
