  $treat = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/batches/$($batch.batchId)/pages/$($page.pageId)/treatments" -ContentType 'application/json' -Body '{"phBefore":6.1,"phAfter":7.3,"reagentBatchNo":"RG-DEMO-01"}'
  $seal = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/batches/$($batch.batchId)/seal" -ContentType 'application/json' -Body '{"requestId":"demo-seal-1"}'
  $rounds = Invoke-RestMethod -Method Get -Uri 'http://localhost:8080/api/pages/P-DEMO/treatments'
  "page=$($page.pageId) batch=$($batch.batchId) enroll=$($enroll.outcome) round=$($treat.roundNo) seal=$($seal.outcome)"
  $rounds | ConvertTo-Json -Compress
}
Stop-Process -Id $proc.Id -Force
